	private void initTool(Program prog)
    {
		if (prog != null) {
			tool = env.showTool(prog);
		}
		else {
			tool = env.showTool();
		}

		tool.addPlugin(typeof(CodeBrowserPlugin).getName());
		tool.addPlugin(typeof(GoToAddressLabelPlugin).getName());
		tool.addPlugin(typeof(CParserPlugin).getName());
		tool.addPlugin(typeof(DataTypeManagerPlugin).getName());
		plugin = getPlugin(tool, typeof(CParserPlugin));

		cparserAction = getAction(plugin, CParserPlugin.PARSE_ACTION_NAME);
		dtmPlugin = getPlugin(tool, typeof(DataTypeManagerPlugin));
	}

